219: function inferFilePathHints(storedPath) {
220:   const segments = String(storedPath || '').split('?')[0].split('/').filter(Boolean)
221:   if (!segments.length) return []
222: 
223:   const last = segments[segments.length - 1]
224:   const isAdd = last.toLowerCase() === 'add'
225:   const isDetail = !isAdd && !isModulePathSegment(last)
226:   const base = (isAdd || isDetail ? segments.slice(0, -1) : segments).join('/')
227:   if (!base) return []
228: 
229:   const hints = []
230:   if (isAdd || isDetail) {
231:     hints.push(`${base}/detail`)
232:   }
233:   hints.push(`${base}/index`, base)
234:   return hints
235: }
236: 
237: function pickRouteByStoredPath(candidates, storedPath) {
238:   if (!candidates.length) return null
239:   if (candidates.length === 1) return candidates[0]
240: 
241:   const detailCandidates = candidates.filter(isDetailRoute)
242:   const pool = detailCandidates.length ? detailCandidates : candidates
243:   const hints = inferFilePathHints(storedPath)
244: 
245:   for (const hint of hints) {
246:     const hit = pool.find((route) => getRouteFilePath(route) === hint)
247:     if (hit) return hit
248:   }
249: 
250:   if (hints.length) {
251:     return null
252:   }
253: 
254:   return pool.find(isDetailRoute) || pool[0]
255: }
