/** 是否「变更记录详情」菜单路由（后端为各类型单独配变更详情菜单时优先命中） */
function isComplexChangeDetailRoute(route) {
  return String(route?.meta?.filePath || '').endsWith('complexChange/detail')
}

/**
 * 解析物业管理区域「变更记录」详情的审批流 busCode：
 * 6 类非物业服务小区与专业化物业管理小区共用同一个「变更记录」菜单，
 * 但审批流为「社区提交、街道审核」，故按小区类型取对应类型详情菜单的 meta.busCode。
 * ① 专业化物业管理小区（1）或未识别类型 → 退回共用变更记录菜单 busCode；
 * ② 非物业服务小区 → 优先取该类型专属变更详情菜单（若后端已配），否则取该类型详情菜单；
 * ③ 未配置类型菜单 busCode → 退回共用菜单 busCode，保证原流程不受影响。
 * 待办任务自带的 query.busCode 由 flowApi.resolveFlowApiBusCode 优先处理，此处不覆盖。
 * @param {object} router vue-router 实例
 * @param {string|number} complexManageType 小区类型码
 * @param {string} [fallbackBusCode] 共用变更记录菜单的 busCode
 * @returns {string} 实际使用的审批流 busCode
 */
export function resolveComplexChangeFlowBusCode(router, complexManageType, fallbackBusCode = '') {
  const fallback = String(fallbackBusCode ?? '').trim()
  const type = String(complexManageType ?? '').trim()
  if (!NON_PROPERTY_SERVICE_TYPES.includes(type)) return fallback
  const routes = typeof router?.getRoutes === 'function' ? router.getRoutes() : []
  const candidates = routes.filter((r) => typeSegmentIndex(r.path, type) >= 0 && String(r.meta?.busCode ?? '').trim())
  if (!candidates.length) return fallback
  const hit = candidates.find(isComplexChangeDetailRoute) || candidates[0]
  return String(hit.meta.busCode).trim() || fallback
}

